import {createActivity,activityAction,activityMarkup} from './activities.js';
let extraActivity;
import {read,write,erase,removeKeys} from './storage.js';
import {starterButtons,defaults,categories,escapeHTML as e,phrase} from './data.js';
import {companions,character,companionArt,symbol} from './characters.js';
import {stories,storyById} from './stories.js';
import {validateProfile,speechPreferences} from './profiles.js';
import {homeWorld,friendsPage,storyLibrary,storyReader,storyFinished,profilesPage,accountPage} from './world.js';
import {initializeNavigation} from './navigation.js';
import {togetherPage} from './together.js';
import {quickEditor,quickRow,fitCommunication,cancelWordEffects,prepareEffect,playWordEffect,popPicture} from './communication.js';
import {donationPage,updateDonation,reviewDonation} from './donations.js';
import {fallbackAnnouncements,validateAnnouncements,updateHeaderLinks,updatesPage} from './updates.js';
let announcements=fallbackAnnouncements,announcementReads=[],updatesLoading=false,appUpdateAvailable=false;
import {aiPreviewMarkup} from './ai-preview.js';
initializeNavigation();
let quickChoices=null;
window.addEventListener('resize',()=>requestAnimationFrame(fitCommunication));
window.addEventListener('anaia-shell-resize',()=>requestAnimationFrame(fitCommunication));
let practiceMode='';
const main=document.querySelector('main');
let profiles=[],activeProfileId='default',profileEditing='',storyProgress={},storyId='',storyPage=0,storyEnded=false,requestedGame='';
const profileKeys=['settings','buttons','entries','categories','storyProgress'];
const artChoices=['yes','no','help','stop','water','food','rest','happy','sad','person','play','music'];
function activeProfile(){return profiles.find(p=>p.id===activeProfileId)||{id:'default',nickname:settings.nickname||'My first profile',companion:'tala',ageBand:'child',sex:'',voiceStyle:'suggested',birthday:''};}
function profileKey(key,pid=activeProfileId){return pid==='default'?key:`profile:${pid}:${key}`;}
async function activateProfile(pid){
 const profile=profiles.find(p=>p.id===pid);if(!profile)throw Error('This profile could not be found.');
 const [nextSettings,nextButtons,nextEntries,nextCategories,nextProgress]=await Promise.all([read(profileKey('settings',pid),defaults),read(profileKey('buttons',pid),starterButtons),read(profileKey('entries',pid),[]),read(profileKey('categories',pid),[]),read(profileKey('storyProgress',pid),{})]);
 await write('activeProfile',pid);
 quickChoices=null;activeProfileId=pid;settings={...defaults,...nextSettings,nickname:profile.nickname};buttons=nextButtons;entries=nextEntries;customCategories=nextCategories;storyProgress=nextProgress;selected='';activeCategory='All';editButton='';editEntry='';storyId='';storyEnded=false;game='';
 if('speechSynthesis'in window)speechSynthesis.cancel();
}
async function persistProfiles(next){if(!storageReady)throw Error('Storage is unavailable. Reload before changing profiles.');await write('profiles',next);profiles=next;}
async function rememberStory(extra={}){if(!storyId)return;const next={...storyProgress,[storyId]:{...storyProgress[storyId],page:storyPage,finished:storyEnded,...extra}};if(await save('storyProgress',next))storyProgress=next;}
function storyView(){return storyId?(storyEnded?storyFinished(settings,storyId):storyReader(settings,storyId,storyPage,storyProgress,!!config.aiStoryNarration&&navigator.onLine)):storyLibrary(settings,storyProgress);}
function nextSteps(){return '<section class="next-steps" aria-label="Keep exploring"><a href="#communication">Communication</a><a href="#play">Play & Learn</a><a href="#stories">Story Garden</a><a href="#home">Home</a></section>';}

let storageReady=false;
let settings={...defaults},buttons=structuredClone(starterButtons),entries=[],customCategories=[],selected='',activeCategory='All',game='',editButton='',editEntry='',filterDate='',deferredInstall=null,offlineReady=false,config={bannerPlaceholder:false};
const $=s=>document.querySelector(s);
const id=()=>crypto.randomUUID();
function notify(message){$('#notice').textContent=message;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',5000);}
async function save(key,value){if(!storageReady){notify('Local storage could not be loaded. Reload to retry; existing saved data has not been changed.');return false;}try{await write(profileKeys.includes(key)?profileKey(key):key,value);return true;}catch{notify('Could not save on this device. Export your data and check available storage.');return false;}}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function allCategories(){return [...new Set([...categories,...customCategories,...buttons.map(b=>b.category)])];}
function applySettings(){document.documentElement.style.setProperty('--tile-size',settings.size==='extra'?'190px':'140px');document.documentElement.style.setProperty('--columns',settings.columns);document.documentElement.style.setProperty('--gap',settings.spacing+'px');document.documentElement.classList.toggle('no-motion',!settings.animations);document.documentElement.lang=settings.language==='fil'?'fil':'en';}
function speak(text,after){$('#ai-voice-preview')?.pause();$('#story-audio')?.pause();if(!('speechSynthesis'in window)){notify('Speech is unavailable in this browser. Your selected message is still shown.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);const preference=speechPreferences(activeProfile(),settings,speechSynthesis.getVoices());utterance.onend=()=>{if(after)after();};utterance.lang=preference.lang;utterance.rate=preference.rate;utterance.pitch=preference.pitch;if(preference.voice)utterance.voice=preference.voice;utterance.onerror=event=>{if(!['interrupted','canceled'].includes(event.error))notify('Voice could not play. Try a device-installed voice or read the displayed message.');};speechSynthesis.speak(utterance);}
function picture(button){const starter=starterButtons.find(b=>b.id===button.id);const art=button.art??(starter?.icon===button.icon?starter?.art:'');return button.photo?`<img src="${e(button.photo)}" alt="">`:artChoices.includes(art)?symbol(art,'communication-picture'):`<span class="picture" aria-hidden="true">${e(button.icon||'⭐')}</span>`;}
function back(){return '<a class="back" href="#home">← Home</a>';}
function MainPageBannerAd(){return config.bannerPlaceholder?'<aside class="banner" aria-label="Advertisement development placeholder">Advertisement · Development placeholder — no live ads</aside>':'';}
function home(){return `${MainPageBannerAd()}${homeWorld(settings,activeProfile(),storyProgress,installMarkup())}`;}
function updateInstallAccess(){const area=$('#global-install');if(!area)return;area.innerHTML=isInstalled()?'':deferredInstall?'<button class="secondary" data-native-install>↓ Install ANAIA</button>':isIOS()?'<a class="button secondary" href="#install">↓ Install ANAIA</a>':'';}
async function requestInstall(){const prompt=deferredInstall;if(!prompt)return;deferredInstall=null;updateInstallAccess();await prompt.prompt();const result=await prompt.userChoice;notify(result.outcome==='accepted'?'Installation requested. Your browser will confirm when it is complete.':'You can install later when your browser offers it.');render();}
function installPage(){if(isInstalled())return `${back()}<h1>ANAIA is open in app mode.</h1><p>You can keep using communication, games, and stories here.</p><a class="button" href="#communication">Open communication</a>`;return `${back()}<p class="eyebrow">Keep ANAIA close</p><h1>Install ANAIA${isIOS()?' on your iPad or iPhone':''}</h1><p>Add ANAIA to your Home Screen so it is easy to find next time. Installation is completed by your browser.</p>${deferredInstall?'<button data-action="install">Install ANAIA</button>':''}<section class="panel install-guide"><h2>On iPad or iPhone</h2><ol><li><strong>Open ANAIA in Safari.</strong> If you’re inside another app, open this website directly in Safari.</li><li><strong>Tap Share <span class="share-symbol" aria-label="square with upward arrow">↑</span></strong> in Safari’s toolbar. If you cannot see it, look in Safari’s <strong>…</strong> menu.</li><li><strong>Scroll down and choose Add to Home Screen.</strong> This option is in Safari’s menu, not inside this page.</li><li>If <strong>Open as Web App</strong> appears, turn it on. Then tap <strong>Add</strong>.</li><li>Find the ANAIA icon on your Home Screen and open it.</li></ol><p class="small">Safari doesn’t let a website complete these steps automatically. If Add to Home Screen is missing, check the Share menu’s Edit Actions option if available. A managed iPad may restrict installation.</p></section><section class="panel"><h2>On Android or a supported desktop browser</h2><p>Use the Install ANAIA button when your browser offers installation, or look for Install app / Add to Home screen in its menu. Browser support varies.</p></section><p>Open ANAIA online once and allow caching before testing offline use. Some device voices require an internet connection.</p><a class="button secondary" href="#home">Back to ANAIA</a>`;}
function installMarkup(){if(isInstalled())return '';if(deferredInstall)return '<button data-action="install">Install ANAIA</button>';if(isIOS())return '<a class="button secondary" href="#install">↓ Install ANAIA on iPad / iPhone</a>';return '';}
function isInstalled(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
function isIOS(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
function communication(){const visible=quickChoices?.buttons||buttons.filter(b=>activeCategory==='All'||b.category===activeCategory);return `<section class="communication-board"><div class="row board-heading"><h1>${e(quickChoices?.question||'What would you like to say?')}</h1>${quickChoices?'<button class="secondary" data-end-quick>Full board · End quick choices</button>':'<a class="button secondary" href="#settings">Caregiver settings</a>'}</div><div class="message communication-message" id="message" role="status" aria-live="off">${e(selected||'Press a picture to speak')}</div>${quickEditor(quickChoices,buttons)}${quickChoices?'<div class="row"><button class="secondary" data-quick-safety="help">Help me</button><button class="secondary" data-quick-safety="stop">Stop</button></div>':`<details class="board-categories"><summary>Category: ${e(activeCategory)}</summary><div class="tabs" aria-label="Communication categories">${['All',...allCategories()].map(c=>`<button data-category="${e(c)}" aria-pressed="${activeCategory===c}">${e(c)}</button>`).join('')}</div></details>`}<div class="grid communication-grid" data-count="${visible.length}">${visible.map(b=>`<button class="tile" data-phrase="${e(b.id)}" aria-pressed="${selected===phrase(b,settings.language)}">${picture(b)}<span>${e(phrase(b,settings.language))}</span></button>`).join('')}</div><details class="board-help"><summary>Touch, speech & sound options</summary><p>Press again to repeat. ${settings.steadyTouch!==false?'Swipe between pictures to scroll; pinch to zoom.':'Swipe to scroll.'} A selection starts a conversation; confirm choices when needed. Offline speech needs a device-installed voice. Messages stay visible if audio is unavailable.</p><label class="check"><input type="checkbox" id="communication-effects" ${settings.communicationEffects?'checked':''}>Optional water and music sounds after speech (quiet synthesized effects)</label><p>Other words use speech only. Change animation preferences in caregiver settings. Effects never delay the spoken message.</p></details></section>`;}

const activities=[['cause','✨','Touch & Discover','A little response to every touch.'],['animals','🐾','Animal Friends','Meet animals and hear their names.'],['colors','🔵','Colors & Shapes','Explore color, shape, and sound.'],['favorites','⭐','My Favorites','Familiar pictures chosen by you.'],['garden','🌼','Grow a Garden','Plant flowers, undo, and explore.'],['pairs','🧩','Picture Pairs','Find familiar friends, without a timer.'],['scene','☀️','Make a Little Scene','Choose weather, friends, and places.']];
function play(){if(!game)return `${back()}<p class="eyebrow">Play & Learn</p><h1>A little wonder. No rush.</h1><p>Choose an activity. There are no scores, timers, or wrong answers.</p><div class="cards">${activities.map(([key,icon,title,desc])=>`<button class="card" data-game="${key}">${key==='cause'?companionArt('bituin','activity-companion'):key==='animals'?companionArt('maya','activity-companion'):key==='colors'?companionArt('kiko','activity-companion'):['garden','pairs','scene'].includes(key)?`<span class="picture" aria-hidden="true">${icon}</span>`:symbol('person','destination-icon')}<h2>${title}</h2><p>${desc}</p></button>`).join('')}</div><section class="panel row between"><div><h2>A story to play along with</h2><p>Meet Kiko and explore shapes at your own pace.</p></div><button class="secondary" data-open-story="kikos-own-pace">Read Kiko’s story →</button></section><p class="small">Recreational and educational activities, not professional therapy. Sounds are ${settings.sounds?'on':'off'}; change preferences in caregiver settings.</p>`;
if(['garden','pairs','scene'].includes(game)){if(extraActivity?.id!==game)extraActivity=createActivity(game,settings.complexity==='simple');return `<button class="secondary" data-action="games-back">← Activities</button><h1>${activities.find(a=>a[0]===game)[2]}</h1><p>No timer. Explore, stop, or start again whenever you like.</p>${activityMarkup(extraActivity)}<button class="secondary" data-activity="restart">Start again</button>`;}
let items=game==='cause'?[['🌻','A flower grows'],['🫧','Gentle bubbles'],['🌈','A rainbow appears'],['⭐','A little star']]:game==='animals'?[['🐱','Cat'],['🐶','Dog'],['🐮','Cow'],['🐑','Sheep'],['🦆','Duck'],['🐦','Bird']]:game==='colors'?[['🔴','Red circle'],['🟦','Blue square'],['🔺','Red triangle'],['🟨','Yellow square'],['🟢','Green circle'],['💜','Purple heart']]:[];
if(settings.complexity==='simple')items=items.slice(0,4);
return `<button class="secondary" data-action="games-back">← Activities</button><h1>${activities.find(a=>a[0]===game)[2]}</h1><div id="game-result" class="result" role="status" aria-live="polite">Choose any picture</div><div class="grid">${game==='favorites'?buttons.filter(b=>b.favorite).map(b=>`<button class="tile" data-play="${e(phrase(b,settings.language))}" data-emoji="${e(b.icon)}">${picture(b)}<span>${e(phrase(b,settings.language))}</span></button>`).join(''):items.map(([icon,label])=>`<button class="tile" data-play="${e(label)}" data-emoji="${icon}"><span class="picture" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('')}</div>${game==='favorites'&&!buttons.some(b=>b.favorite)?'<p class="empty">No favorites yet. A caregiver can mark communication pictures as favorites in settings, including personal photos.</p>':''}<p class="small">${game==='animals'?'Animal recordings are not bundled. When sounds are enabled, the device voice speaks the animal’s name.':'Each touch gives a visual response. Sound is optional.'}</p>`;}
function journal(){const current=entries.find(x=>x.id===editEntry);return `${back()}<p class="eyebrow">My Little World · Caregiver assisted</p><h1>The little things, remembered.</h1><p>Record what you noticed, in your own words. This is a private observation journal, not a medical assessment.</p><details class="panel" ${current?'open':''}><summary>${current?'Edit observation':'＋ Record an observation'}</summary><form id="journal-form"><div class="fields"><label>Date and time<input name="time" type="datetime-local" required value="${e(current?.time||localTime())}"></label><label>Mood or engagement observation<input name="mood" maxlength="200" value="${e(current?.mood)}" placeholder="Smiled during music"></label><label>Sleep notes<input name="sleep" maxlength="500" value="${e(current?.sleep)}"></label><label>Comfort observations<input name="comfort" maxlength="500" value="${e(current?.comfort)}"></label><label>Favorite activities<input name="activities" maxlength="500" value="${e(current?.activities)}"></label><label>Preferences<input name="preferences" maxlength="500" value="${e(current?.preferences)}"></label></div><label>Other observations<textarea name="notes" maxlength="3000">${e(current?.notes)}</textarea></label><div class="row"><button type="submit">${current?'Save changes':'Save observation'}</button>${current?'<button type="button" class="secondary" data-action="cancel-entry">Cancel edit</button>':''}</div></form></details><section class="panel"><h2>Recorded observations</h2><p>${entries.length} ${entries.length===1?'entry':'entries'} recorded. ${entries.filter(x=>x.activities).length} entries mention activities. These are counts of your records, not inferred feelings or medical conclusions.</p><label>Filter by date<input id="date-filter" type="date" value="${e(filterDate)}"></label><div class="row"><button class="secondary" data-action="clear-filter">Show all dates</button><button class="secondary" data-action="export-journal">Export JSON</button><button class="secondary" data-action="export-csv">Export CSV</button></div><div id="history">${history()}</div></section>`;}
function localTime(){const date=new Date();return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function history(){const visible=entries.filter(x=>!filterDate||x.time.startsWith(filterDate)).sort((a,b)=>b.time.localeCompare(a.time));return visible.length?visible.map(x=>`<article class="entry"><h3>${e(new Date(x.time).toLocaleString())}</h3>${['mood','sleep','comfort','activities','preferences','notes'].filter(k=>x[k]).map(k=>`<p><strong>${{mood:'Engagement',sleep:'Sleep',comfort:'Comfort',activities:'Activities',preferences:'Preferences',notes:'Notes'}[k]}:</strong> ${e(x[k])}</p>`).join('')}<div class="row"><button class="secondary" data-edit-entry="${x.id}">Edit observation</button><button class="danger" data-delete-entry="${x.id}">Delete observation</button></div></article>`).join(''):'<p class="empty">No observations for these dates. Your next small discovery can start here.</p>';}
function options(values,selectedValue){return values.map(v=>{const [value,label]=Array.isArray(v)?v:[v,v];return `<option value="${e(value)}" ${String(value)===String(selectedValue)?'selected':''}>${e(label)}</option>`;}).join('');}
function settingsPage(){const b=buttons.find(x=>x.id===editButton);return `${back()}<p class="eyebrow">Caregiver space</p><h1>Make room for your way.</h1><p>For parents and caregivers. This area is separate from play, but is not password locked. Essential communication is always available.</p><div class="row"><a class="button secondary" href="#communication">Open communication now</a><a class="button secondary" href="#profiles">Profiles & voices</a><a class="button secondary" href="#friends">Choose a companion</a></div><form id="settings-form" class="panel"><h2>Comfort & access</h2><label class="check"><input name="steadyTouch" type="checkbox" ${settings.steadyTouch!==false?'checked':''}>Steady touch: prevent scrolling that starts on a communication picture</label><p class="small">Leave spaces between pictures for scrolling. Pinch zoom and keyboard access remain available. Turn this off if swiping directly on pictures works better.</p><p class="small">For ages 13 and under, ANAIA prefers a child-labeled device voice when available. Otherwise it adjusts pace and pitch. iPad voices may still sound adult; a true child voice is not guaranteed. Choose a specific voice or manual pitch below to override suggestions.</p><div class="fields"><label>Child nickname (optional)<input name="nickname" maxlength="40" value="${e(settings.nickname)}" autocomplete="off"></label><label>Starter phrase language<select name="language">${options([['en','English'],['fil','Filipino']],settings.language)}</select></label><label>Button size<select name="size">${options([['large','Large'],['extra','Extra large']],settings.size)}</select></label><label>Grid columns (mobile uses at most two)<select name="columns">${options(['1','2','3','4'],settings.columns)}</select></label><label>Spacing<select name="spacing">${options([['16','Comfortable'],['24','Wide'],['32','Extra wide']],settings.spacing)}</select></label><label>Visual complexity<select name="complexity">${options([['simple','Fewer pictures'],['expanded','More pictures']],settings.complexity)}</select></label><label>Voice<select name="voice" id="voices">${voiceOptions()}</select></label><label class="check"><input name="adaptiveVoice" type="checkbox" ${settings.adaptiveVoice!==false?'checked':''}>Suggest voice pace and pitch from profile age</label><label>Manual pitch (used when age suggestions are off)<input name="pitch" type="range" min="0.7" max="1.4" step="0.05" value="${settings.pitch||1}"></label><label>Speech rate<input name="rate" type="range" min="0.5" max="1.5" step="0.1" value="${settings.rate}"></label><label class="check"><input name="sounds" type="checkbox" ${settings.sounds?'checked':''}>Enable game speech and gentle tones</label><label class="check"><input name="communicationEffects" type="checkbox" ${settings.communicationEffects?'checked':''}>Optional communication sounds: water bubbles and music notes after speech</label><label class="check"><input name="animations" type="checkbox" ${settings.animations?'checked':''}>Enable gentle animations (device reduced motion takes priority)</label><label>Optional avatar (JPEG, PNG, WebP; up to 2 MB)<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"></label></div>${settings.avatar?`<img class="avatar" src="${e(settings.avatar)}" alt="Saved avatar"><label class="check"><input type="checkbox" name="removeAvatar">Remove avatar</label>`:''}<div class="row"><button>Save settings</button><button type="button" class="secondary" data-action="test-voice">Test saved voice</button></div></form><section class="panel" id="ai-preview-panel">${aiPreviewMarkup(config)}</section><section class="panel"><h2>Pictures & phrases</h2><p>Photos stay on this device. Essential starter and safety buttons cannot be deleted; their words and pictures can be adapted.</p><form id="button-form"><input type="hidden" name="id" value="${e(b?.id)}"><div class="fields"><label>English phrase<input name="en" required maxlength="120" value="${e(b?.en)}"></label><label>Filipino phrase (optional)<input name="fil" maxlength="120" value="${e(b?.fil)}"></label><label>Picture symbol or emoji<input name="icon" maxlength="12" value="${e(b?.icon||'⭐')}"></label><label>Category<select name="category">${options(allCategories(),b?.category||'Needs')}</select></label><label>Built-in picture<select name="art">${options([['','Use emoji / symbol'],...artChoices.map(a=>[a,a[0].toUpperCase()+a.slice(1)])],b?.art??(starterButtons.find(x=>x.id===b?.id)?.icon===b?.icon?starterButtons.find(x=>x.id===b?.id)?.art:''))}</select></label><label>Personal photo (JPEG, PNG, WebP; up to 2 MB)<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="check"><input name="favorite" type="checkbox" ${b?.favorite?'checked':''}>Show in My Favorites</label>${b?.photo?'<label class="check"><input type="checkbox" name="removePhoto">Remove saved photo</label>':''}</div><div class="row"><button>${b?'Save picture changes':'Add picture button'}</button>${b?'<button type="button" class="secondary" data-action="cancel-button">Cancel edit</button>':''}</div></form><form id="category-form"><label>New custom category<input name="category" required maxlength="40"></label><button class="secondary">Add category</button></form><div>${buttons.map((x,i)=>`<article class="entry"><strong>${e(x.icon)} ${e(x.en)}</strong> · ${e(x.category)} ${x.favorite?'⭐':''}<div class="row"><button class="secondary" data-edit-button="${x.id}">Edit ${e(x.en)}</button><button class="secondary" data-move="${x.id}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${e(x.en)} earlier">↑</button><button class="secondary" data-move="${x.id}" data-direction="1" ${i===buttons.length-1?'disabled':''} aria-label="Move ${e(x.en)} later">↓</button>${!x.id.startsWith('starter-')?`<button class="danger" data-delete-button="${x.id}">Delete ${e(x.en)}</button>`:''}</div></article>`).join('')}</div></section><section class="panel"><h2>Your data & privacy</h2><p><a class="button secondary" href="/update.html">Check for ANAIA updates</a> Update app files without clearing local records.</p><p>Current profile: <strong>${e(activeProfile().nickname)}</strong>. Other profiles have separate communication boards and journals. Profiles, birthdays, and gender information stay on this device. Google sign-in is not connected.</p><p>Pictures, settings, and journal entries are stored only in this browser’s IndexedDB. Clearing site data, private browsing, or changing devices can lose them. Export regularly; exported files contain private information.</p><div class="row"><button class="secondary" data-action="export-all">Export all local data</button><button class="secondary" data-action="persistent">Request durable device storage</button><button class="danger" data-action="erase">Delete all local data</button><a href="#privacy">Read privacy notice</a></div></section><section class="panel"><h2>ANAIA Free · Optional support</h2><p>All current features are free. No purchase or donation is required.</p><a class="button secondary" href="#donate">Free plan & optional donation</a></section><section class="panel"><h2>Alternative access</h2><p>Use Tab or Shift+Tab to move between controls and Enter or Space to activate buttons. Compatible switches or eye-gaze systems may map to these browser controls. Configure and test your device’s accessibility tools with a caregiver. ANAIA has no built-in switch scanning or eye tracking.</p><p>Offline status: ${offlineReady?'Application shell cached on this device.':'Offline readiness has not yet been confirmed.'}</p></section>`;}
function voiceOptions(){const voices='speechSynthesis'in window?speechSynthesis.getVoices():[];return options([['','Device default'],...voices.map(v=>[v.voiceURI,`${v.name} · ${v.lang}${v.localService?' · device voice':' · may need internet'}`])],settings.voice);}
function premium(){return donationPage();}
function privacy(){return `${back()}<h1>Your little world stays yours.</h1><section class="panel"><h2>Privacy notice</h2><p>ANAIA stores communication buttons, photos, settings, and caregiver observations locally in this browser. Google sign-in is planned but is not connected. Multiple local profiles may include an optional birthday and gender for voice suggestions. Each profile has separate local records. They are accessible to anyone using this browser profile. This version does not upload these records, use analytics, or include an advertising SDK or external AI service for child records. If configured, a caregiver can play a fixed AI-generated greeting, and Story Garden can narrate published pages with an AI voice. Only the fixed greeting and published story-page scripts are sent to OpenAI by the server; selections, names, birthdays, photos and journal entries are not included.</p><p>Your device may be shared. Anyone who can open this browser profile can access its local journal and settings. Use device security and a private browser profile where appropriate. Local records are not an encrypted medical record system.</p><p>The hosting provider receives ordinary website requests, including your IP address. ANAIA does not put communication phrases or journal contents in URLs, network requests, or server logs.</p><h2>Offline & speech</h2><p>After successful initial caching, the app shell, starter pictures, and locally saved data can be used offline. Installed device voices may work offline; network voices may not. Audio requires browser permission through a user interaction and a working device output. Photos you add are stored locally, not in the service-worker cache.</p><p>Browser storage can be removed by the browser or by clearing site data. Export your data regularly from caregiver settings. Exported files are private; store them safely. Profiles and story places are local too. Import and cross-device synchronization are not implemented yet. Local profiles are not password protected; Google sign-in is only a planned screen.</p><h2>Advertising & purchases</h2><p>Live advertising is disabled. A development placeholder, if enabled by the operator, appears only at the top of the home page. No child-facing activity contains advertising or purchase prompts. ANAIA is free. Optional caregiver donations, when configured, open an external payment provider. That provider processes the transfer under its own privacy terms; ANAIA does not collect payment credentials, send child records, or verify completed donations.</p><h2>Care & interpretation</h2><p>A selected image is a communication opportunity, not definitive consent or a diagnosis. Confirm choices where appropriate. Journal summaries only count observations; they do not infer feelings, predict medical events, or recommend treatments.</p></section>`;}
function render(focus=false){$('#ai-voice-preview')?.pause();$('#story-audio')?.pause();applySettings();const route=location.hash.slice(1)||'home';document.body.classList.toggle('steady-touch',route==='communication'&&settings.steadyTouch!==false);main.classList.toggle('communication-page',route==='communication');main.innerHTML=({home,communication,play,journal,settings:settingsPage,premium,donate:donationPage,updates:()=>updatesPage(announcements,announcementReads,updatesLoading,storageReady,appUpdateAvailable),privacy,profiles:()=>profilesPage(profiles,activeProfileId,profileEditing),friends:()=>friendsPage(activeProfile()),stories:storyView,account:accountPage,install:installPage,together:()=>togetherPage(practiceMode,settings.language)}[route]||home)();if(['communication','play','journal'].includes(route))main.insertAdjacentHTML('beforeend',nextSteps());document.querySelectorAll('.app-nav a, .app-footer nav a').forEach(link=>{if(link.hash==='#'+route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.title=`ANAIA · ${{home:'Welcome',communication:'Communication Corner',play:'Play & Learn',journal:'My Little World',settings:'Caregiver settings',premium:'Free plan & donations',donate:'Free plan & donations',updates:'Updates & announcements',privacy:'Privacy',profiles:'Profiles & voices',friends:'Meet the companions',stories:'Tala’s Story Garden',account:'Caregiver account',install:'Install ANAIA',together:'Everyday moments'}[route]||'Welcome'}`;updateInstallAccess();updateDonation(config);updateHeaderLinks(route,announcements,announcementReads,appUpdateAvailable);main.dataset.ready='true';requestAnimationFrame(fitCommunication);if(focus){main.focus();scrollTo(0,0);}}
async function photo(file){if(!file?.size)return '';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Choose a JPEG, PNG, or WebP image no larger than 2 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/webp',.8);}
async function handleWorldClick(t){
 if(t.dataset.practice){practiceMode=t.dataset.practice;render();document.querySelector('.practice-panel')?.scrollIntoView({block:'start'});return true;}
 if(t.dataset.practicePhrase){const words={water:['I want water.','Gusto ko ng tubig.'],music:['I want music.','Gusto ko ng musika.'],break:['I need a break.','Kailangan kong magpahinga.']}[t.dataset.practicePhrase];if(words){const text=words[settings.language==='fil'?1:0];$('#practice-message').textContent=text;speak(text);}return true;}

 if(t.dataset.openStory||t.dataset.restartStory){
  storyId=t.dataset.openStory||t.dataset.restartStory;const story=storyById(storyId);if(!story)throw Error('This story is not available.');
  const saved=storyProgress[storyId];storyPage=t.dataset.restartStory||saved?.finished?0:Math.min(saved?.bookmark??saved?.page??0,story.pages.length-1);storyEnded=false;
  if('speechSynthesis'in window)speechSynthesis.cancel();location.hash='stories';await rememberStory();render(true);return true;
 }
 if(t.dataset.storyStep){$('#story-audio')?.pause();if('speechSynthesis'in window)speechSynthesis.cancel();const story=storyById(storyId);const next=storyPage+Number(t.dataset.storyStep);if(next>=story.pages.length)storyEnded=true;else storyPage=Math.max(0,next);await rememberStory();render(true);return true;}
 if(t.dataset.storyChoice!==undefined){const page=storyById(storyId)?.pages[storyPage],choice=page?.choices?.[Number(t.dataset.storyChoice)];if(!choice)return true;const words=choice[settings.language==='fil'?2:1];$('#story-choice-feedback').textContent=words;speak(words);return true;}
 if(t.dataset.launchGame){requestedGame=t.dataset.launchGame;if(location.hash==='#play'){game=requestedGame;requestedGame='';render(true);}else location.hash='play';return true;}
 if(t.dataset.useProfile){if(!storageReady)throw Error('Reload to load storage before switching profiles.');await activateProfile(t.dataset.useProfile);render(true);notify('Profile changed. Pictures, voice, journal, and stories now use this profile.');return true;}
 if(t.dataset.editProfile){profileEditing=t.dataset.editProfile;render();$('#profile-form').scrollIntoView();$('#profile-form input[name=nickname]').focus();return true;}
 if(t.dataset.deleteProfile){const pid=t.dataset.deleteProfile;if(pid==='default')return true;if(!storageReady)throw Error('Storage could not be loaded. Reload before deleting.');if(!confirm('Permanently delete this profile and its communication pictures, journal, and story places? Export first if you want a copy.'))return true;
  const remaining=profiles.filter(p=>p.id!==pid);await removeKeys(profileKeys.map(key=>profileKey(key,pid)),{profiles:remaining,activeProfile:activeProfileId===pid?'default':activeProfileId});profiles=remaining;if(activeProfileId===pid)await activateProfile('default');profileEditing='';render(true);notify('Local profile deleted.');return true;}
 if(t.dataset.companion){if(!companions.some(c=>c.id===t.dataset.companion))return true;await persistProfiles(profiles.map(p=>p.id===activeProfileId?{...p,companion:t.dataset.companion}:p));render();$(`[data-companion="${t.dataset.companion}"]`)?.focus({preventScroll:true});notify(character(t.dataset.companion).name+' is your companion.');return true;}
 switch(t.dataset.action){case'refresh-ai-preview':{if(!navigator.onLine){notify('You’re offline. Device speech remains available.');break;}t.disabled=true;try{const response=await fetch('/config.json',{cache:'no-store',signal:AbortSignal.timeout(4000)});if(!response.ok)throw Error('unavailable');const data=await response.json();config.aiVoicePreviewStatus=data.aiVoicePreviewStatus;const panel=$('#ai-preview-panel');if(panel){panel.innerHTML=aiPreviewMarkup(config);panel.querySelector('button')?.focus({preventScroll:true});}}catch{notify('Could not check the sample. Device speech remains available.');}finally{t.disabled=false;}break;}
  case 'read-story': {const audio=$('#story-audio');if(audio){if('speechSynthesis'in window)speechSynthesis.cancel();$('#story-audio-status').textContent='Preparing narration… You can use device voice at any time.';audio.play().then(()=>{if(audio.isConnected)$('#story-audio-status').textContent='AI storyteller · playing this page.';}).catch(()=>{if(audio.isConnected)$('#story-audio-status').textContent='AI narration could not play. Choose Use device voice, or read together.';});return true;}const page=storyById(storyId)?.pages[storyPage];if(page)speak(page[settings.language==='fil'?'fil':'en']);return true;}
  case 'device-story':{const page=storyById(storyId)?.pages[storyPage];if(page)speak(page[settings.language==='fil'?'fil':'en']);return true;}
  case 'stop-story':$('#story-audio')?.pause();if('speechSynthesis'in window)speechSynthesis.cancel();notify('Reading stopped.');return true;
  case 'bookmark-story':await rememberStory({bookmark:storyPage});render();notify('Your place is saved in this local profile.');return true;
  case 'cancel-profile':profileEditing='';render();return true;
  case 'preview-profile-voice':speak(settings.language==='fil'?'Kumusta! Ito ang boses ko.':'Hello! This is my voice. I can take my time.');return true;
 }
 return false;
}
