if(t.dataset.activity){const action=t.dataset.activity;if(action==='restart')extraActivity=createActivity(game,settings.complexity==='simple');else activityAction(extraActivity,action,t.dataset.value);render();const selector=`[data-activity="${action}"][data-value="${t.dataset.value||''}"]`;const target=document.querySelector(selector);(target&&!target.disabled?target:$('#activity-status'))?.focus({preventScroll:true});if(settings.sounds)speak(extraActivity.message);return;}

