let audioContext;function tone(){try{audioContext||=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.frequency.value=440;gain.gain.setValueAtTime(.08,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.3);oscillator.start();oscillator.stop(audioContext.currentTime+.3);}catch{notify('Sound is unavailable. The visual response is still active.');}}
