render();connection();
refreshAnnouncements();
if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});const registration=await navigator.serviceWorker.ready;const detectUpdate=()=>{const ready=!!(registration.waiting&&navigator.serviceWorker.controller);if(ready!==appUpdateAvailable){appUpdateAvailable=ready;const route=location.hash.slice(1)||'home';updateHeaderLinks(route,announcements,announcementReads,appUpdateAvailable);if(route==='updates')render();}};if(registration.installing)registration.installing.addEventListener('statechange',()=>requestAnimationFrame(detectUpdate));registration.addEventListener('updatefound',()=>{registration.installing?.addEventListener('statechange',()=>requestAnimationFrame(detectUpdate));});navigator.serviceWorker.addEventListener('controllerchange',detectUpdate);detectUpdate();const worker=registration.active;if(worker){const channel=new MessageChannel();channel.port1.onmessage=event=>{if(event.data?.type==='CACHE_READY'){offlineReady=true;connection();}};worker.postMessage({type:'CHECK_CACHE'},[channel.port2]);}}catch{notify('Offline setup was unsuccessful. Keep this page open and try reloading while connected.');}}

async function refreshAnnouncements(showFeedback=false){if(updatesLoading)return;if(!navigator.onLine){if(showFeedback)notify('You’re offline. Saved announcements remain available.');return;}updatesLoading=true;try{const response=await fetch('/announcements.json',{cache:'no-store',signal:AbortSignal.timeout(3000)});if(!response.ok)throw Error('unavailable');const data=await response.json();const next=validateAnnouncements(data.announcements);announcements=next;if(storageReady)await save('announcements',next);if(showFeedback)notify('Latest announcements loaded.');}catch{if(showFeedback)notify('Could not check for announcements. Your saved announcements are still available.');}finally{updatesLoading=false;const route=location.hash.slice(1)||'home';updateHeaderLinks(route,announcements,announcementReads,appUpdateAvailable);if(route==='updates'){render();if(showFeedback)document.querySelector('[data-update-refresh]')?.focus({preventScroll:true});}}}

main.addEventListener('error',event=>{if(event.target.id==='ai-voice-preview'){const status=$('#ai-preview-status');if(status)status.textContent='The AI sample could not play. Check your connection and sample availability. Device speech remains available.';}},true);

main.addEventListener('error',event=>{if(event.target.id==='story-audio'){const status=$('#story-audio-status');if(status)status.textContent='Online narration is unavailable. Choose Use device voice, or read together.';}},true);

main.addEventListener('play',event=>{if(event.target.id==='story-audio'&&'speechSynthesis'in window)speechSynthesis.cancel();},true);
